from collections import Counter
G = load()

def count_output_groups(demo_in, sep_indices, col1, col2):
    combos = [(demo_in[i][col1], demo_in[i][col2]) for i in sep_indices]

    # Count unique consecutive transitions (including starting point)
    groups = []
    if len(combos) > 0:
        groups.append(combos[0])
        for c in combos[1:]:
            if c != groups[-1]:
                groups.append(c)

    print(f"Merged groups: {len(groups)}")
    return len(groups), groups

# Test with various column pairs
